package com.mannaggia.app

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * Shared saint-picking logic — the port of mannaggia.sh lives here so it can be
 * called from MainActivity, MannaggiaTileService and MannaggiaWidgetProvider.
 *
 * Saints come from assets/santi.txt (Wikidata, CC0), generated by
 * tools/genera_santi.py, so the app works offline.
 */
object Mannaggia {

    private const val SAINTS_ASSET = "santi.txt"

    @Volatile
    private var saints: List<String>? = null

    /** Build the final phrase shown to the user. */
    fun phraseOf(saint: String): String = "Mannaggia $saint!"

    /** Pick a random saint from the bundled list (loaded once, then cached). */
    suspend fun randomSaint(context: Context): String = withContext(Dispatchers.IO) {
        val list = saints ?: loadSaints(context).also { saints = it }
        if (list.isEmpty()) "Sant'Anonimo" else list.random()
    }

    /** Read assets/santi.txt, skipping blank lines and `#` comments. */
    private fun loadSaints(context: Context): List<String> =
        context.applicationContext.assets.open(SAINTS_ASSET).bufferedReader(Charsets.UTF_8).useLines { lines ->
            lines.map { it.trim() }
                .filter { it.isNotEmpty() && !it.startsWith("#") }
                .toList()
        }
}
